package com.silverguardian.prototype.data;

import android.content.Context;import android.content.SharedPreferences;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;
import com.silverguardian.prototype.R;import com.silverguardian.prototype.data.dao.*;import com.silverguardian.prototype.reminder.MedicineAlarmScheduler;import com.silverguardian.prototype.health.HealthAlertService;import com.silverguardian.prototype.health.HealthMetricEvaluator;import com.silverguardian.prototype.models.*;
import java.text.SimpleDateFormat;import java.util.*;

public class Repository{
 private static Repository instance;
 private final Context appContext;private final ElderlyDbHelper dbHelper;private final UserDao userDao;private final HealthDao healthDao;private final MedicineDao medicineDao;private final AlbumDao albumDao;private final ChatDao chatDao;private final MemoryDao memoryDao;private final EmergencyDao emergencyDao;private final FamilyDao familyDao;private final MedicineLibraryDao libraryDao;private final FraudTipDao fraudDao;private final SharedPreferences session;
 private final List<User>users=new ArrayList<>();private final List<HealthData>healthData=new ArrayList<>();private final List<FamilyMember>familyMembers=new ArrayList<>();private final List<Medicine>medicines=new ArrayList<>();private final List<AlbumPhoto>photos=new ArrayList<>();private final List<ChatMessage>chatMessages=new ArrayList<>();private final List<MemoryRecord>memories=new ArrayList<>();private final List<EmergencyAlert>emergencyAlerts=new ArrayList<>();private final List<FraudTip>fraudTips=new ArrayList<>();private final List<MedicineLibraryItem>medicineLibrary=new ArrayList<>();private final List<BluetoothDeviceMock>bluetoothDevices=new ArrayList<>();
 private int activeUserId;

 private Repository(Context c){appContext=c.getApplicationContext();dbHelper=new ElderlyDbHelper(appContext);userDao=new UserDao(dbHelper);healthDao=new HealthDao(dbHelper);medicineDao=new MedicineDao(dbHelper);albumDao=new AlbumDao(dbHelper);chatDao=new ChatDao(dbHelper);memoryDao=new MemoryDao(dbHelper);emergencyDao=new EmergencyDao(dbHelper);familyDao=new FamilyDao(dbHelper);libraryDao=new MedicineLibraryDao(dbHelper);fraudDao=new FraudTipDao(dbHelper);session=appContext.getSharedPreferences("elder_session",Context.MODE_PRIVATE);activeUserId=session.getInt("active_user_id",-1);seedDevices();}
 public static synchronized Repository init(Context c){Context app=c.getApplicationContext();if(instance==null||instance.appContext!=app){if(instance!=null)instance.dbHelper.close();instance=new Repository(app);}instance.load();return instance;}
 public static Repository getInstance(){if(instance==null)throw new IllegalStateException("Repository not initialized");return instance;}

 private void load(){SQLiteDatabase db=dbHelper.getWritableDatabase();userDao.seedIfEmpty(db);users.clear();users.addAll(userDao.readAll());for(User u:users)ElderlyDbHelper.seedDefaultTemplates(db,u.id);if(!findUser(activeUserId)&&!users.isEmpty())activeUserId=users.get(0).id;if(activeUserId>0)session.edit().putInt("active_user_id",activeUserId).apply();reloadActive();}
 private void reloadActive(){healthData.clear();familyMembers.clear();medicines.clear();photos.clear();chatMessages.clear();memories.clear();emergencyAlerts.clear();fraudTips.clear();medicineLibrary.clear();if(activeUserId<0)return;healthData.addAll(healthDao.readAll(activeUserId));familyMembers.addAll(familyDao.readAll(activeUserId));medicines.addAll(medicineDao.readAll(activeUserId,today()));photos.addAll(albumDao.readAll(activeUserId));chatMessages.addAll(chatDao.readAll(activeUserId));memories.addAll(memoryDao.readAll(activeUserId));emergencyAlerts.addAll(emergencyDao.readAll(activeUserId));fraudTips.addAll(fraudDao.readAll(activeUserId));medicineLibrary.addAll(libraryDao.search(activeUserId,""));}
 private boolean findUser(int id){for(User u:users)if(u.id==id)return true;return false;}
 private void seedDevices(){if(!bluetoothDevices.isEmpty())return;bluetoothDevices.add(new BluetoothDeviceMock(1,"Blood Pressure Monitor BP-80","blood_pressure","126/81","Ready"));bluetoothDevices.add(new BluetoothDeviceMock(2,"Pulse Oximeter OX-2","blood_oxygen","98","Ready"));bluetoothDevices.add(new BluetoothDeviceMock(3,"Fitness Band HR-6","heart_rate","74","Ready"));}

 public List<User>getUsers(){return users;}public List<HealthData>getHealthData(){return healthData;}public List<HealthData>getTodayHealthData(){return healthDao.readToday(activeUserId);}public List<FamilyMember>getFamilyMembers(){return familyMembers;}public List<Medicine>getMedicines(){return medicines;}public List<AlbumPhoto>getPhotos(){return photos;}public List<ChatMessage>getWelcomeMessages(){return chatMessages;}public List<MemoryRecord>getMemories(){return memories;}public List<FraudTip>getFraudTips(){return fraudTips;}public List<EmergencyAlert>getEmergencyAlerts(){return emergencyAlerts;}public List<MedicineLibraryItem>getMedicineLibrary(){return medicineLibrary;}public List<BluetoothDeviceMock>getBluetoothDevices(){return bluetoothDevices;}public int getActiveUserId(){return activeUserId;}
 public void setActiveUser(int id){if(!findUser(id))return;activeUserId=id;session.edit().putInt("active_user_id",id).apply();reloadActive();}
 public User addUser(String n,String p,int age,String cond){return addUser(n,p,age,cond,"","");}
 public User addUser(String n,String p,int age,String cond,String q,String a){SQLiteDatabase db=dbHelper.getWritableDatabase();int id;db.beginTransaction();try{id=userDao.add(db,n,p,age,cond,q,a);ElderlyDbHelper.seedDefaultTemplates(db,id);db.setTransactionSuccessful();}finally{db.endTransaction();}load();for(User u:users)if(u.id==id)return u;throw new IllegalStateException("User insert failed");}
 public void deleteUser(User u){userDao.delete(u.id);load();}
 public HealthData addHealthData(String type,String value,String status){return addHealthData(type,value,status,"");}
 public HealthData addHealthData(String type,String value,String status,String notes){String finalStatus=status==null||status.isEmpty()?HealthMetricEvaluator.status(type,value):status;int id=healthDao.add(activeUserId,type,value,finalStatus,notes);HealthData d=new HealthData(id,type,value,finalStatus,notes,nowDateTime(),R.drawable.ic_info);healthData.add(0,d);HealthAlertService.checkAndAlert(appContext,d);return d;}
 public Medicine addMedicine(String n,String t,String time,String method,String desc){return addMedicine(n,t,time,method,desc,0,0,10);}
 public Medicine addMedicine(String n,String t,String time,String method,String desc,int advance,int repeats,int interval){int id=medicineDao.add(activeUserId,n,t,time,method,desc,advance,repeats,interval);Medicine m=new Medicine(id,n,t,time,method,desc,"",false,advance,repeats,interval);medicines.add(0,m);MedicineAlarmScheduler.schedule(appContext,activeUserId,activeUserName(),m);return m;}
 public void deleteMedicine(Medicine m){MedicineAlarmScheduler.cancel(appContext,activeUserId,m);medicineDao.delete(m.id);medicines.remove(m);}public void toggleMedicineTaken(Medicine m,boolean taken){medicineDao.setTaken(activeUserId,m.id,taken,today());m.takenToday=taken;}
 public AlbumPhoto addPhoto(String title,String category,String msg){return addPhoto("","",title,category,msg);}
 public AlbumPhoto addPhoto(String privatePath,String publicUri,String title,String category,String msg){int id=albumDao.add(activeUserId,privatePath,publicUri,title,category,msg);AlbumPhoto p=new AlbumPhoto(id,privatePath,publicUri,title,"家属上传的照片",category,"家属",false,category,msg);photos.add(0,p);return p;}
 public void deletePhoto(AlbumPhoto p){com.silverguardian.prototype.album.PhotoStorage.delete(appContext,p.url,p.publicUri);albumDao.delete(p.id);photos.remove(p); }public void toggleFavorite(AlbumPhoto p){p.favorite=!p.favorite;albumDao.setFavorite(p.id,p.favorite);}
 public void addChatMessage(String text,String type){chatMessages.add(new ChatMessage(text,type,now()));chatDao.add(activeUserId,text,type);}public void resetChatSession(String welcome){chatDao.clearForUser(activeUserId);chatMessages.clear();addChatMessage(welcome,ChatMessage.TYPE_AI);}
 public MemoryRecord addMemory(String c,String category){int id=memoryDao.add(activeUserId,c,category);MemoryRecord r=new MemoryRecord(id,c,category,"刚刚");memories.add(0,r);return r;}public void deleteMemory(MemoryRecord r){memoryDao.delete(r.id);memories.remove(r);}
 public EmergencyAlert addEmergencyAlert(String msg){int id=emergencyDao.add(activeUserId,msg);EmergencyAlert a=new EmergencyAlert(id,nowDateTime(),msg,"待处理");emergencyAlerts.add(0,a);return a;}
 public List<MedicineLibraryItem>searchMedicineLibrary(String k){return libraryDao.search(activeUserId,k);}public void addLibraryItem(MedicineLibraryItem i){libraryDao.upsert(activeUserId,i);medicineLibrary.clear();medicineLibrary.addAll(libraryDao.search(activeUserId,""));}public void updateLibraryItem(MedicineLibraryItem i){libraryDao.update(activeUserId,i);reloadActive();}public void deleteLibraryItem(MedicineLibraryItem i){libraryDao.delete(activeUserId,i.id);reloadActive();}
 public Set<String>medicineTypes(){Set<String>s=new LinkedHashSet<>();s.add("ALL_TYPES");for(Medicine m:medicines)s.add(m.type);return s;}public Set<String>photoCategories(){Set<String>s=new LinkedHashSet<>();s.add("ALL");for(AlbumPhoto p:photos)s.add(p.category);return s;}public Set<String>memoryCategories(){Set<String>s=new LinkedHashSet<>();s.add("ALL");for(MemoryRecord m:memories)s.add(m.category);return s;}public Set<String>fraudCategories(){Set<String>s=new LinkedHashSet<>();s.add("ALL");for(FraudTip f:fraudTips)s.add(f.category);return s;}
 private String activeUserName(){for(User u:users)if(u.id==activeUserId)return u.name;return "老人家";} public String now(){return new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date());}private String nowDateTime(){return new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.getDefault()).format(new Date());}private String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.getDefault()).format(new Date());}
}